func Decode(in []byte) (*Record, error) {
	r := &reader{buf: in}
	r.ws()
	v, err := r.decodeRecord()
	if err != nil {
		return nil, err
	}
	r.ws()
	if r.pos < len(r.buf) {
		return nil, r.refuse("trailing_bytes")
	}
	if err := r.derive(v); err != nil {
		return nil, err
	}
	return v, nil
}

var ContentTerms = []string{"abstraction.job/base@1", "abstraction.job/intent@1", "abstraction.download/ranges@1", "abstraction.job/delegation@1", "abstraction.job/envelope@1", "abstraction.job/terminal@1", "abstraction.job/recall@1", "abstraction.job/step@1"}

var ContentStripCritical = map[string]bool{
	"abstraction.download/ranges@1": true,
	"abstraction.job/step@1":        true,
}

func (r *reader) derive(v *Record) error {
	in := map[string]bool{}
	for _, n := range v.Content {
		in[n] = true
	}
	known := map[string]bool{}
	for _, n := range ContentTerms {
		known[n] = true
	}
	kept := v.Critical[:0]
	for _, n := range v.Critical {
		switch {
		case ContentStripCritical[n]:
			continue
		case !known[n]:
			return r.refuse("unknown_critical")
		case !in[n]:
			return r.refuse("not_a_subset")
		}
		kept = append(kept, n)
	}
	v.Critical = kept
	if (true) != in["abstraction.job/base@1"] {
		return r.refuse("content_mismatch")
	}
	if (v.Intent != nil) != in["abstraction.job/intent@1"] {
		return r.refuse("content_mismatch")
	}
	if (Member(v.Checkpoint, "verified")) != in["abstraction.download/ranges@1"] {
		return r.refuse("content_mismatch")
	}
	if (v.Delegation != nil) != in["abstraction.job/delegation@1"] {
		return r.refuse("content_mismatch")
	}
	if (v.Envelope != nil) != in["abstraction.job/envelope@1"] {
		return r.refuse("content_mismatch")
	}
	if (v.State == "complete" || v.State == "failed" || v.State == "cancelled") != in["abstraction.job/terminal@1"] {
		return r.refuse("content_mismatch")
	}
	if (v.Lease.Recall != nil) != in["abstraction.job/recall@1"] {
		return r.refuse("content_mismatch")
	}
	if (v.Progress.Step != nil) != in["abstraction.job/step@1"] {
		return r.refuse("content_mismatch")
	}
	return nil
}

// [DEF-A8] Whether an opaque value is an object naming this member with
// something other than null. The key is decoded, so two spellings of one name
// are one name; the value is neither decoded nor judged.
func Member(v Raw, name string) bool {
	r := &reader{buf: []byte(v)}
	r.ws()
	if r.at() != '{' {
		return false
	}
	r.pos++
	r.ws()
	for r.at() == '"' {
		k, err := r.str()
		if err != nil {
			return false
		}
		r.ws()
		r.pos++
		r.ws()
		if k == name {
			return r.at() != 'n'
		}
		if r.skipValue() != nil {
			return false
		}
		r.ws()
		if r.at() != ',' {
			return false
		}
		r.pos++
		r.ws()
	}
	return false
}

// Refusals is in the order two of them are chosen between.

var Refusals = []string{"malformed", "bad_string", "number_spelling", "wrong_type", "bad_timestamp", "depth_exceeded", "duplicate_key", "duplicate_field", "unknown_field", "missing_field", "trailing_bytes", "unknown_critical", "not_a_subset", "content_mismatch"}

func RefusalRank(word string) int {
	for i, w := range Refusals {
		if w == word {
			return i
		}
	}
	return -1
}

func rawFlat(out []byte, s string) []byte {
	for i := 0; i < len(s); {
		c := s[i]
		switch {
		case c == ' ' || c == '\t' || c == '\n' || c == '\r':
			i++
		case c == '"':
			j := i + 1
			for j < len(s) {
				if s[j] == '\\' {
					j += 2
					continue
				}
				if s[j] == '"' {
					j++
					break
				}
				j++
			}
			out = append(out, s[i:j]...)
			i = j
		default:
			out = append(out, c)
			i++
		}
	}
	return out
}

func strsFlat(out []byte, v []string) []byte {
	out = append(out, '[')
	for i, s := range v {
		if i > 0 {
			out = append(out, ',')
		}
		out = esc(out, s)
	}
	return append(out, ']')
}

func rawsFlat(out []byte, v []Raw) []byte {
	out = append(out, '[')
	for i, s := range v {
		if i > 0 {
			out = append(out, ',')
		}
		out = rawFlat(out, s)
	}
	return append(out, ']')
}

func (r *reader) rawList() ([]Raw, error) {
	if r.at() != '[' {
		return nil, r.refuse("wrong_type")
	}
	if err := r.enter(); err != nil {
		return nil, err
	}
	r.pos++
	out := []Raw{}
	r.ws()
	if r.at() != ']' {
		for {
			r.ws()
			v, err := r.rawValue()
			if err != nil {
				return nil, err
			}
			out = append(out, v)
			r.ws()
			if r.at() != ',' {
				break
			}
			r.pos++
		}
	}
	if r.at() != ']' {
		return nil, r.refuse("malformed")
	}
	r.pos++
	r.depth--
	return out, nil
}

var Operations = []string{"submit", "load", "list", "orphans", "claimable", "claim", "renew", "release", "set_intent", "recall", "write"}

func IsOperation(name string) bool {
	for _, o := range Operations {
		if o == name {
			return true
		}
	}
	return false
}

const UnknownOperation = "unknown_op"

var Verdicts = []string{"not_found", "lease_held", "stale_epoch", "conflict", "lease_expired", "terminal", "invalid", "unknown_schema", "unknown_op", "not_supported", "other"}

func IsVerdict(name string) bool {
	for _, v := range Verdicts {
		if v == name {
			return true
		}
	}
	return false
}

func encWireRequest(out []byte, v *Request) []byte {
	out = append(out, '{')
	out = esc(out, "op")
	out = append(out, ':')
	out = esc(out, v.Op)
	if v.Id != "" {
		out = append(out, ',')
		out = esc(out, "id")
		out = append(out, ':')
		out = esc(out, v.Id)
	}
	if v.Owner != "" {
		out = append(out, ',')
		out = esc(out, "owner")
		out = append(out, ':')
		out = esc(out, v.Owner)
	}
	if v.Epoch != 0 {
		out = append(out, ',')
		out = esc(out, "epoch")
		out = append(out, ':')
		out = num(out, v.Epoch)
	}
	if v.TtlMs != 0 {
		out = append(out, ',')
		out = esc(out, "ttl_ms")
		out = append(out, ':')
		out = num(out, v.TtlMs)
	}
	if v.Want != "" {
		out = append(out, ',')
		out = esc(out, "want")
		out = append(out, ':')
		out = esc(out, v.Want)
	}
	if v.By != "" {
		out = append(out, ',')
		out = esc(out, "by")
		out = append(out, ':')
		out = esc(out, v.By)
	}
	if v.Reason != "" {
		out = append(out, ',')
		out = esc(out, "reason")
		out = append(out, ':')
		out = esc(out, v.Reason)
	}
	if v.Record != "" {
		out = append(out, ',')
		out = esc(out, "record")
		out = append(out, ':')
		out = rawFlat(out, v.Record)
	}
	if v.Base != "" {
		out = append(out, ',')
		out = esc(out, "base")
		out = append(out, ':')
		out = rawFlat(out, v.Base)
	}
	return append(out, '}')
}

func EncodeRequest(v *Request) []byte {
	return encWireRequest(nil, v)
}

func DecodeRequest(in []byte) (*Request, error) {
	r := &reader{buf: in}
	r.ws()
	v, err := r.decodeRequest()
	if err != nil {
		return nil, err
	}
	r.ws()
	if r.pos < len(r.buf) {
		return nil, r.refuse("trailing_bytes")
	}
	return v, nil
}

func encWireResponse(out []byte, v *Response) []byte {
	out = append(out, '{')
	first := true
	if v.Kind != "" {
		first = false
		out = esc(out, "kind")
		out = append(out, ':')
		out = esc(out, v.Kind)
	}
	if v.Error != "" {
		if !first {
			out = append(out, ',')
		}
		first = false
		out = esc(out, "error")
		out = append(out, ':')
		out = esc(out, v.Error)
	}
	if v.Id != "" {
		if !first {
			out = append(out, ',')
		}
		first = false
		out = esc(out, "id")
		out = append(out, ':')
		out = esc(out, v.Id)
	}
	if v.Record != "" {
		if !first {
			out = append(out, ',')
		}
		first = false
		out = esc(out, "record")
		out = append(out, ':')
		out = rawFlat(out, v.Record)
	}
	if len(v.Records) != 0 {
		if !first {
			out = append(out, ',')
		}
		first = false
		out = esc(out, "records")
		out = append(out, ':')
		out = rawsFlat(out, v.Records)
	}
	if v.Bool {
		if !first {
			out = append(out, ',')
		}
		first = false
		out = esc(out, "bool")
		out = append(out, ':')
		if v.Bool {
			out = append(out, 't', 'r', 'u', 'e')
		} else {
			out = append(out, 'f', 'a', 'l', 's', 'e')
		}
	}
	if len(v.Unreadable) != 0 {
		if !first {
			out = append(out, ',')
		}
		first = false
		out = esc(out, "unreadable")
		out = append(out, ':')
		out = strsFlat(out, v.Unreadable)
	}
	return append(out, '}')
}

func EncodeResponse(v *Response) []byte {
	return encWireResponse(nil, v)
}

func DecodeResponse(in []byte) (*Response, error) {
	r := &reader{buf: in}
	r.ws()
	v, err := r.decodeResponse()
	if err != nil {
		return nil, err
	}
	r.ws()
	if r.pos < len(r.buf) {
		return nil, r.refuse("trailing_bytes")
	}
	return v, nil
}
